// 2026년 한국 공휴일 목록 (이미지 참고 반영)
const holidays2026 = [
  "2026-01-01", // 신정
  "2026-02-16", "2026-02-17", "2026-02-18", // 설날 연휴
  "2026-03-01", "2026-03-02", // 3.1절 및 대체공휴일
  "2026-05-05", // 어린이날
  "2026-05-24", "2026-05-25", // 부처님 오신 날 및 대체공휴일
  "2026-06-06", // 현충일
  "2026-08-15", "2026-08-17", // 광복절 및 대체공휴일
  "2026-09-24", "2026-09-25", "2026-09-26", // 추석 연휴
  "2026-10-03", "2026-10-05", // 개천절 및 대체공휴일
  "2026-10-09", // 한글날
  "2026-12-25", // 크리스마스
];

// 현재 시간 기준 KST(한국 표준시) 계산
const now = new Date();
const kstDate = new Date(now.getTime() + (9 * 60 * 60 * 1000));

const year = kstDate.getUTCFullYear();
const month = String(kstDate.getUTCMonth() + 1).padStart(2, '0');
const day = String(kstDate.getUTCDate()).padStart(2, '0');
const dateString = `${year}-${month}-${day}`;

const hours = kstDate.getUTCHours();
const minutes = kstDate.getUTCMinutes();
const dayOfWeek = kstDate.getUTCDay(); // 0: 일요일, 6: 토요일

// 1. 주말 체크
const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);

// 2. 공휴일 체크
const isHoliday = holidays2026.includes(dateString);

// 3. 업무 시간 체크 (08:30 ~ 18:30)
const currentTimeInMinutes = (hours * 60) + minutes;
const startMinutes = (8 * 60) + 30;
const endMinutes = (18 * 60) + 30;
const isBusinessHours = (currentTimeInMinutes >= startMinutes && currentTimeInMinutes <= endMinutes);

// 최종 실행 여부 결정
const shouldRun = !isWeekend && !isHoliday && isBusinessHours;

return {
  shouldRun,
  status: shouldRun ? "정상 작동" : "중단 (주말/휴일/시간외)",
  debug: {
    kstTime: `${hours}:${minutes}`,
    date: dateString,
    day: ["일", "월", "화", "수", "목", "금", "토"][dayOfWeek]
  }
};

// AI가 내뱉은 텍스트(output)를 가져옵니다.
const rawText = $input.item.json.output;

try {
  // 1. JSON 파싱
  const parsedData = JSON.parse(rawText);

  // 2. urls 배열 내의 각 링크를 n8n이 인식할 수 있는 개별 아이템 형태로 변환
  // [ { json: { url: "링크1" } }, { json: { url: "링크2" } } ] 형태로 반환됩니다.
  return parsedData.urls.map(url => {
    return {
      url: url
    };
  });

} catch (error) {
  // 에러 발생 시 추적을 위해 원본 텍스트 반환
  return [{
    error: "JSON 파싱 실패",
    rawText: rawText
  }];
}

